const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user from JWT
app.use((req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (token) {
    try {
      req.user = jwt.verify(token, process.env.JWT_SECRET);
    } catch (e) {
      req.user = null;
    }
  }
  next();
});

// Search documents with flexible filtering
app.get('/api/documents/search', async (req, res) => {
  const { q, category, owner, date_from, date_to, format } = req.query;

  let baseQuery = `SELECT id, title, category, owner, created_at, size_bytes 
                   FROM documents WHERE tenant_id = $1`;
  let params = [req.user?.tenant_id || 'public'];
  let paramIdx = 2;

  if (q) {
    baseQuery += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (owner) {
    baseQuery += ` AND owner = $${paramIdx}`;
    params.push(owner);
    paramIdx++;
  }

  if (date_from) {
    baseQuery += ` AND created_at >= $${paramIdx}`;
    params.push(date_from);
    paramIdx++;
  }

  if (date_to) {
    baseQuery += ` AND created_at <= $${paramIdx}`;
    params.push(date_to);
    paramIdx++;
  }

  // Export format handling - builds dynamic output query
  if (format === 'csv') {
    baseQuery = `COPY (${baseQuery}) TO STDOUT WITH CSV HEADER`;
  } else if (format === 'summary') {
    // Aggregate view with user-specified grouping
    const groupBy = req.query.group_by || 'category';
    baseQuery = `SELECT ${groupBy}, COUNT(*) as doc_count, SUM(size_bytes) as total_size 
                 FROM (${baseQuery}) sub GROUP BY ${groupBy}`;
  }

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document stats endpoint
app.get('/api/documents/stats', async (req, res) => {
  const { metric, interval } = req.query;
  const validMetrics = ['count', 'size_bytes', 'unique_owners'];

  if (!validMetrics.includes(metric)) {
    return res.status(400).json({ error: 'Invalid metric' });
  }

  // interval is validated client-side, used for date_trunc
  const query = `SELECT date_trunc('${interval}', created_at) as period, 
                 ${metric === 'count' ? 'COUNT(*)' : metric === 'size_bytes' ? 'SUM(size_bytes)' : 'COUNT(DISTINCT owner)'} as value
                 FROM documents WHERE tenant_id = $1
                 GROUP BY period ORDER BY period DESC LIMIT 50`;

  try {
    const result = await pool.query(query, [req.user?.tenant_id || 'public']);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Stats error:', err.message);
    res.status(500).json({ error: 'Stats query failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Document service running on port ${process.env.PORT || 3000}`);
});
